import{_ as e,o as n,c as i,a6 as t}from"./chunks/framework.DycQjAfF.js";const h=JSON.parse('{"title":"SOP Stock Opname","description":"Stock opname harian secara bergilir (cycle count) untuk mencocokkan stok fisik dengan catatan sistem.","frontmatter":{"title":"SOP Stock Opname","description":"Stock opname harian secara bergilir (cycle count) untuk mencocokkan stok fisik dengan catatan sistem.","status":"ditinjau","dasar":"Instruksi Kerja Stock Opname Harian Gudang Teknik","nomor_dokumen":null,"versi":0.3,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-20T00:00:00.000Z","kategori":"SOP","sumber":["ik-gudang-teknik","ppt-gudang-teknik"],"kata_kunci":["SOP","stock opname","stock opname harian","hitung fisik","cycle count","cycle counting","stock sheet","kartu stok","selisih","stock discrepancy","akar masalah","penyesuaian","akurasi stok","stock keeper","supervisor","kepala gudang","fast moving"]},"headers":[],"relativePath":"sop/stock-opname.md","filePath":"sop/stock-opname.md"}'),s={name:"sop/stock-opname.md"};function l(r,a,u,k,d,o){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="sop-stock-opname" tabindex="-1">SOP Stock Opname <a class="header-anchor" href="#sop-stock-opname" aria-label="Permalink to &quot;SOP Stock Opname&quot;">​</a></h1><p class="lead">Di Gudang Teknik, stock opname dilakukan <strong>setiap hari secara bergilir</strong> (<em>cycle count</em>). Setiap hari, sebagian barang dihitung, bukan seluruh gudang sekaligus. Isinya diringkas dari Instruksi Kerja Stock Opname Harian Gudang Teknik.</p><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Memastikan catatan stok di sistem sama dengan jumlah fisik barang di gudang. Pengecekan rutin ini membantu:</p><ul><li>mendeteksi kehilangan atau kerusakan barang dengan cepat,</li><li>mencegah kekosongan stok,</li><li>menemukan kesalahan input data.</li></ul><h2 id="berlaku-untuk" tabindex="-1">Berlaku untuk <a class="header-anchor" href="#berlaku-untuk" aria-label="Permalink to &quot;Berlaku untuk&quot;">​</a></h2><p>Penghitungan fisik sebagian persediaan setiap hari secara bergilir. Fokusnya:</p><ul><li>barang <strong>fast moving</strong> (perputarannya cepat),</li><li>barang <strong>bernilai tinggi</strong>,</li><li><strong>verifikasi barang masuk dan keluar</strong> hari itu.</li></ul><h2 id="peran" tabindex="-1">Peran <a class="header-anchor" href="#peran" aria-label="Permalink to &quot;Peran&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Peran</th><th>Tanggung jawab</th></tr></thead><tbody><tr><td data-label="Peran"><strong>Stock Keeper</strong></td><td data-label="Tanggung jawab">Menghitung fisik barang langsung di lapangan, memeriksa kondisinya (rusak atau kedaluwarsa), dan memberi label jika perlu.</td></tr><tr><td data-label="Peran"><strong>Supervisor atau Kepala Gudang</strong></td><td data-label="Tanggung jawab">Memvalidasi hasil hitung harian, mengawasi agar sesuai SOP, dan mengecek ulang jika ada anomali atau selisih.</td></tr></tbody></table><h2 id="yang-perlu-disiapkan" tabindex="-1">Yang perlu disiapkan <a class="header-anchor" href="#yang-perlu-disiapkan" aria-label="Permalink to &quot;Yang perlu disiapkan&quot;">​</a></h2><ul><li>Komputer, printer, dan sistem ERP/WMS.</li><li>Daftar stok harian (<em>stock sheet</em>) atau kartu stok untuk kategori yang dijadwalkan.</li><li>Alat tulis: pulpen, pensil, dan clipboard.</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li><strong>Siapkan daftar.</strong> Cetak atau siapkan <em>stock sheet</em> harian atau kartu stok untuk kategori barang yang dijadwalkan hari itu.</li><li><strong>Hentikan atau batasi transaksi.</strong> Hentikan sementara penerimaan dan pengeluaran barang di area yang akan dihitung, supaya tidak ada selisih karena transaksi yang sedang berjalan.</li><li><strong>Hitung fisik</strong> barang secara langsung (<em>actual count</em>).</li><li><strong>Tulis jumlah aktual</strong> di lembar kerja stock opname, dan pastikan kondisi fisik barang baik. Beri label jika ada barang rusak atau kedaluwarsa.</li><li><strong>Bandingkan</strong> jumlah fisik dengan saldo di sistem atau pembukuan harian.</li><li><strong>Kalau ada selisih</strong> (barang kurang atau lebih): <ul><li>cari akar masalahnya, misalnya salah input, barang tidak ditaruh di tempatnya, atau barang yang diambil tidak sesuai,</li><li>hitung ulang,</li><li>telusuri dokumen transaksinya.</li></ul></li><li><strong>Serahkan hasil ke Supervisor atau Kepala Gudang</strong> untuk divalidasi. Penyesuaian di sistem dilakukan setelah penyebab selisih ditemukan dan hasilnya divalidasi.</li></ol><h2 id="penyebab-selisih-yang-sering-terjadi" tabindex="-1">Penyebab selisih yang sering terjadi <a class="header-anchor" href="#penyebab-selisih-yang-sering-terjadi" aria-label="Permalink to &quot;Penyebab selisih yang sering terjadi&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Penyebab</th><th>Contoh</th></tr></thead><tbody><tr><td data-label="Penyebab">Salah input</td><td data-label="Contoh">Jumlah atau nomor material salah ketik saat mencatat barang masuk atau keluar.</td></tr><tr><td data-label="Penyebab">Barang tidak di tempatnya</td><td data-label="Contoh">Barang ditaruh di rak lain, sehingga tidak terhitung di lokasinya.</td></tr><tr><td data-label="Penyebab">Pengambilan tidak sesuai</td><td data-label="Contoh">Barang yang diambil berbeda jenis atau jumlahnya dengan reservasi.</td></tr></tbody></table><h2 id="cek-sebelum-selesai" tabindex="-1">Cek sebelum selesai <a class="header-anchor" href="#cek-sebelum-selesai" aria-label="Permalink to &quot;Cek sebelum selesai&quot;">​</a></h2><ul class="daftar-periksa"><li>Transaksi di area yang dihitung sudah dihentikan atau dibatasi.</li><li>Semua barang dalam daftar hari ini sudah dihitung.</li><li>Kondisi barang sudah dicek, dan barang rusak atau kedaluwarsa sudah diberi label.</li><li>Item yang selisih sudah dihitung ulang dan dokumennya ditelusuri.</li><li>Hasil sudah divalidasi Supervisor atau Kepala Gudang sebelum sistem disesuaikan.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Saat menghitung di rak</p><ul><li>Jangan memanjat rak untuk menghitung barang di atas. Gunakan tangga yang stabil.</li><li>Kembalikan barang ke posisi semula dengan stabil setelah dihitung.</li></ul></div><h2 id="baca-juga" tabindex="-1">Baca juga <a class="header-anchor" href="#baca-juga" aria-label="Permalink to &quot;Baca juga&quot;">​</a></h2><ul><li><a href="/WareHouse/alur-kerja/stock-opname">Alur Stock Opname</a></li><li><a href="/WareHouse/tutorial/hitung-fisik">Mencatat Hasil Hitung Fisik</a></li></ul>',22)])])}const b=e(s,[["render",l]]);export{h as __pageData,b as default};
